example_usage:
// example terraform usage (stringified)
module "vpc_scaffolder" {
  source = "git::https://github.com/redwood-inference/terraform-modules.git//vpc_scaffolder?ref=v0.1.0-alpha"
  name_prefix = "redwood-staging"
  cidr_block = "10.40.0.0/16"
  az_count = 3
  public_subnet_sizes = ["/24", "/24", "/24"]
  private_subnet_sizes = ["/24", "/24", "/24"]
  enable_nat_gateways = true
  enable_vpc_endpoints = ["s3", "dynamodb", "ecr"]
  canary_rollout = { enabled = true, step_percentages = [10,50,100], probe_duration_minutes = 5 }
  opa_policy_module = "module.policy_guardrails"
}

// CI job outline:
// 1) terraform init; terraform plan -out plan.tfplan
// 2) run snapshotter -> s3://infra-backups/vpc-scaffolder/2025-03-05-1400.tfstate
// 3) run plan-sanitizer to ensure no forbidden deletes
// 4) run canary_orchestrator --plan plan.tfplan --stages 10,50,100
// 5) canary_orchestrator triggers prober lambda and monitors CloudWatch metrics; on pass it continues, on failure it executes rollback script.
